import { describe, it } from "vitest";

// Reading of the error contract: the spec only defines the CLI outcome
// (non-zero exit + stderr). At the domain level, runScenario signals a
// rejected scenario by throwing an Error; no type or message is specified.

describe("quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword, newcomer -> base 100 + 10 first insurance + 5 fee = 115 G");
  it.todo("plain amulet, newcomer -> base 60 + 6 first insurance + 5 fee = 71 G");
  it.todo("plain staff, newcomer -> base 80 + 8 first insurance + 5 fee = 93 G");
  it.todo("plain potion, newcomer -> base 40 + 4 first insurance + 5 fee = 49 G");
  it.todo("2 runes -> base 50 G -> 50 + 5 + 5 = 60 G");
  it.todo("3 runes -> block base 60 G -> 60 + 6 + 5 = 71 G");
  it.todo("4 runes -> no block, base 100 G -> 115 G");
  it.todo("7 runes -> no block, base 175 G -> 192.5 + 5 = 197.5 rounded up to 198 G");
  it.todo("1 moonstone -> base 25 G -> 27.5 + 5 = 32.5 rounded up to 33 G");
  it.todo("2 runes + 1 moonstone -> no block (different types), base 75 G -> 88 G");
  it.todo("3 runes + 3 moonstones -> two blocks, base 120 G -> 137 G");
  it.todo("newcomer with cursed steel sword enchantment 3 -> 165 G");
  it.todo("sword enchantment 4, not cursed -> no high-enchantment surcharge -> 115 G");
  it.todo("sword enchantment exactly 5 -> 30 % high-enchantment surcharge -> 145 G");
  it.todo("cursed sword enchantment 5 -> both surcharges -> 195 G");
  it.todo("cursed sword enchantment 4 -> only curse surcharge -> 165 G");
  it.todo("customer with exactly 2 years -> loyalty discount: 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount -> 115 G");
  it.todo("cursed sword + plain amulet -> curse applies to sword only: 160 + 50 + 16 + 5 = 231 G");
  it.todo("second quote in scenario -> 15 % follow-up discount: 100 + 10 - 15 + 5 = 100 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -> 160 G");
  it.todo("3-year customer, cursed sword enchantment 5 + 1 rune -> 197.5 rounded up to 198 G");
  it.todo("quote with unknown item type broomstick -> throws Error");
});

describe("claim", () => {
  it.todo("5-year customer, silver amulet, fire damage 200 -> payout 100, remainingCap 1100");
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("potion damage 300 -> payout 200, remainingCap 600 (cap 800)");
  it.todo("rune damage 200 -> payout 100, remainingCap 400 (cap 500)");
  it.todo("moonstone damage 150 -> payout 50, remainingCap 450 (cap 500)");
  it.todo("dragon sword enchantment 9, damage 1000 -> 50 % wins: payout 400, remainingCap 1600");
  it.todo("dragon sword enchantment 5, damage 800 -> full: payout 700, remainingCap 1300");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400");
  it.todo("dragon sword exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("sword + amulet, dragon attack 500 + 300 -> deductible per item: payout 600, remainingCap 2600 (cap 3200)");
  it.todo("two swords both damaged 500 -> separate deductibles: payout 800, remainingCap 3200 (cap 4000)");
  it.todo("sword + 3 runes (block), sword damage 500 -> payout 400, remainingCap 3100 (cap 3500)");
  it.todo("cursed sword (premium 165) damage 500 -> cap 2000 from insurance value: remainingCap 1600");
  it.todo("sword, two successive claims of 1500 -> 1400 / 600, then 600 / 0");
  it.todo("steel staff enchantment 9, damage 901 -> 350.5 rounded down to 350, remainingCap 1250");
  it.todo("amulet damaged when only a sword is insured -> throws Error");
  it.todo("damage with unknown item type -> throws Error");
  it.todo("two sword damages but only one sword insured -> throws Error (whole claim rejected)");
  it.todo("damage amount -200 -> throws Error");
});

