input.command:
cat > src/claimOffice.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResults {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;

function quote(step: QuoteStep): QuoteResult {
  const policyBasePremium = step.items.length * SWORD_BASE_PREMIUM;
  const premium = policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
  return { premium: Math.ceil(premium) };
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map(quote) };
}
EOF
